// Reflection model: the parsed and VALIDATED form of <svc>.reflect.json (as generated by
// protoc-gen-qmp and served by QMP_OP_REFLECT). The document may come from another
// process, so every offset and size is bounds-checked here, once; the codec then trusts
// the model.
#ifndef QMPCTL_REFLECT_HPP
#define QMPCTL_REFLECT_HPP

#include <cstdint>
#include <map>
#include <string>
#include <utility>
#include <vector>

#include <nlohmann/json.hpp>

namespace qmpctl {

using Json = nlohmann::ordered_json;

// The "qmp_reflect_version" this qmpctl reads (REFLECT_VERSION in the generator, ADR-011).
constexpr uint32_t kReflectVersion = 1;

enum class Kind { Bool, Int32, UInt32, Int64, UInt64, Float, Double, Enum, String, Bytes, Message };

struct Field {
    std::string name;
    std::string type; // proto type word: "uint32", "string", "enum", "message", ...
    Kind kind = Kind::Bool;
    int number = 0;
    bool repeated = false;
    uint32_t offset = 0;    // of the field inside its message
    uint32_t size = 0;      // of the whole field (array helper included)
    uint32_t elem_size = 0; // one element (== size when not repeated)
    uint32_t max_len = 0;   // string/bytes
    uint32_t max_count = 0; // repeated
    std::string type_name;  // enum or message full name
    std::vector<std::pair<std::string, int32_t>> enum_values;
};

struct Message {
    std::string name;
    uint32_t size = 0; // 0 = zero-field message (no payload)
    std::vector<Field> fields;
};

struct Method {
    std::string name;
    std::string uuri;
    std::string input;
    std::string output;
    uint16_t id = 0;
    bool oneway = false;
};

struct Topic {
    std::string name;
    std::string uuri;
    std::string message;
    std::string mode; // LATEST | QUEUE
    uint16_t id = 0;
    uint32_t depth = 0;
    bool notification = false;
};

struct Service {
    std::string name;         // "Joint"
    std::string full_name;    // "demo.joint.v1.Joint"
    std::string service_name; // uprotocol.service_name, "demo.joint.Joint"
    std::string uuri;
    std::string qnx_path;
    uint16_t service_id = 0;
    uint8_t ver_major = 0;
    uint8_t ver_minor = 0;
    std::vector<Method> methods;
    std::vector<Topic> topics;

    const Method *find_method(const std::string &name_or_id) const;
    const Topic *find_topic(const std::string &name_or_id) const;
    bool matches_name(const std::string &n) const;
};

struct Doc {
    std::vector<Service> services;
    std::map<std::string, Message> messages;
    Json raw; // the document as received, for --json output

    const Message *find_message(const std::string &full_name) const;
    const Service *find_service(uint16_t service_id, uint8_t ver_major) const;
};

// Parses and validates. Returns false and sets err on any malformed or inconsistent input.
bool parse_reflection(const std::string &text, Doc &out, std::string &err);

// "0x8001" or "32769" -> id. Returns false when s is not a number in 0..65535.
bool parse_resource_id(const std::string &s, uint16_t &id);

} // namespace qmpctl
#endif
